import { useEffect } from 'react'
import { useApp } from '../context/AppContext'
import { absolute, resetSeo, setCanonical, setMeta, setMetaOrRemove, setRobots, setTitle, setJsonLd, storefrontOrigin } from '../lib/seo'

/** The API's per-language Open Graph locale, e.g. fr_MA. */
const OG_LOCALE = { fr: 'fr_MA', ar: 'ar_MA', en: 'en_US' }

/**
 * The card every page shares when it has nothing better: the branded
 * og-image.jpg generated by scripts/make-og-image.sh, which carries the
 * logo and the tagline over the hero photograph. Without a default, a page
 * that passes no image (the catalogue, the reviews, a brand without a
 * picture) strips its og:image on the way in and shares as a bare link.
 */
const DEFAULT_IMAGE = '/og-image.jpg'

function absoluteImage(url) {
  if (!url) return null
  if (/^https?:\/\//i.test(url)) return url
  // A crawler never resolves a relative og:image — WhatsApp and Facebook
  // simply show no picture. Product artwork arrives as `/images/...`, so
  // when the bundle was built without a separate API origin it has to be
  // prefixed with the origin it is served from.
  const api = (import.meta.env.VITE_API_URL || storefrontOrigin()).replace(/\/$/, '')
  return `${api}${url.startsWith('/') ? '' : '/'}${url}`
}

/**
 * Applies one page's metadata.
 *
 * Every public page calls this once its data has loaded. resetSeo() runs first
 * so the previous page's tags cannot survive into this one — the common SPA
 * failure is a page rendering with the last product's description, which reads
 * as duplicate content to a crawler and looks plainly broken to a human.
 *
 * `jsonLd` is a payload, not a flag: Product passes a real schema.org object,
 * and the rest pass nothing.
 *
 * `enabled` is for a page that shows another page's view: the home page
 * renders the boutique's own catalogue under its hero, and that catalogue
 * must not write metadata over the home page's. Two writers on the same
 * <head> would fight, and the loser's tags would be the ones a crawler read.
 */
export default function useSeo({
  title,
  description,
  image,
  canonical,
  alternates,
  type = 'website',
  noindex = false,
  jsonLd = null,
  enabled = true,
}) {
  const { locale, t } = useApp()

  useEffect(() => {
    if (!enabled) return

    resetSeo()

    if (title) setTitle(title)

    setMetaOrRemove('description', description)
    setMetaOrRemove('og:title', title)
    setMetaOrRemove('og:description', description)
    // A page that names no image of its own shares the branded card, so the
    // preview always has a picture; only a page that passes an empty string
    // explicitly loses it. The card lives on the storefront host, not the
    // API's, which is why it is resolved through `absolute` while product
    // artwork goes through `absoluteImage`.
    const cardImage = image ? absoluteImage(image) : absolute(DEFAULT_IMAGE)
    setMetaOrRemove('og:image', cardImage)
    setMeta('og:type', type)
    setMeta('og:url', canonical ?? null)
    setMeta('og:locale', OG_LOCALE[locale] ?? 'fr_MA')
    setMeta('og:site_name', t('seo', 'siteName'))

    // The card image is never absent now, so the large-image layout applies
    // to every page rather than only to products.
    setMeta('twitter:card', 'summary_large_image')
    setMetaOrRemove('twitter:title', title)
    setMetaOrRemove('twitter:description', description)
    setMetaOrRemove('twitter:image', cardImage)

    setCanonical({ canonical, alternates })
    setRobots(noindex ? 'noindex, nofollow' : 'index, follow')

    setJsonLd(jsonLd)
  }, [enabled, title, description, image, canonical, JSON.stringify(alternates ?? {}), type, noindex, locale, JSON.stringify(jsonLd)])
}